create type public.coupon_type as enum ('percentage', 'fixed');
create table public.coupons (id uuid primary key default gen_random_uuid(), code text not null unique, type public.coupon_type not null, discount_value numeric(12,2) not null check (discount_value > 0), minimum_order_value numeric(12,2) not null default 0, maximum_discount numeric(12,2), starts_at timestamptz, expires_at timestamptz, usage_limit integer, per_user_usage_limit integer, active boolean not null default true, created_at timestamptz not null default now());
create table public.coupon_usages (id uuid primary key default gen_random_uuid(), coupon_id uuid not null references public.coupons(id), user_id uuid not null references auth.users(id), order_id uuid not null references public.orders(id), created_at timestamptz not null default now(), unique(coupon_id, order_id));
alter table public.orders add column coupon_code text, add column coupon_discount numeric(12,2) not null default 0;
alter table public.coupons enable row level security; alter table public.coupon_usages enable row level security;
create policy "Admins manage coupons" on public.coupons for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "Users view own coupon usage" on public.coupon_usages for select to authenticated using (user_id = auth.uid());
insert into public.coupons (code, type, discount_value, minimum_order_value, maximum_discount, active) values ('BLYVER10', 'percentage', 10, 0, 500, true) on conflict (code) do nothing;
-- This replaces the order function so it validates coupons and calculates the discount inside Postgres.
create or replace function public.create_cod_order(customer_address jsonb, coupon_code_input text default null) returns text language plpgsql security definer set search_path = public as $$ declare v_cart uuid; v_item record; v_product record; v_subtotal numeric := 0; v_delivery numeric; v_order uuid; v_number text; v_coupon record; v_discount numeric := 0; begin select id into v_cart from public.carts where user_id = auth.uid(); if v_cart is null or not exists (select 1 from public.cart_items where cart_id = v_cart) then raise exception 'Your cart is empty'; end if; for v_item in select * from public.cart_items where cart_id = v_cart loop select * into v_product from public.products where id = v_item.product_id and status = 'active' for update; if not found or v_product.stock_quantity < v_item.quantity then raise exception 'One or more items are no longer available'; end if; v_subtotal := v_subtotal + coalesce(v_product.sale_price, v_product.original_price) * v_item.quantity; end loop; if nullif(trim(coupon_code_input), '') is not null then select * into v_coupon from public.coupons where upper(code) = upper(trim(coupon_code_input)) and active and (starts_at is null or starts_at <= now()) and (expires_at is null or expires_at >= now()) for update; if not found or v_subtotal < v_coupon.minimum_order_value or (v_coupon.usage_limit is not null and (select count(*) from public.coupon_usages where coupon_id = v_coupon.id) >= v_coupon.usage_limit) or (v_coupon.per_user_usage_limit is not null and (select count(*) from public.coupon_usages where coupon_id = v_coupon.id and user_id = auth.uid()) >= v_coupon.per_user_usage_limit) then raise exception 'This coupon is not valid for your order'; end if; v_discount := case when v_coupon.type = 'percentage' then v_subtotal * v_coupon.discount_value / 100 else v_coupon.discount_value end; if v_coupon.maximum_discount is not null then v_discount := least(v_discount, v_coupon.maximum_discount); end if; v_discount := least(v_discount, v_subtotal); end if; select delivery_charge into v_delivery from public.site_settings where id = true; v_number := 'BLV-' || to_char(now(), 'YYYYMMDD') || '-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 6)); insert into public.orders (order_number, user_id, customer_address, subtotal, delivery_charge, coupon_code, coupon_discount, total) values (v_number, auth.uid(), customer_address, v_subtotal, v_delivery, case when v_coupon.id is null then null else v_coupon.code end, v_discount, v_subtotal - v_discount + v_delivery) returning id into v_order; if v_coupon.id is not null then insert into public.coupon_usages (coupon_id, user_id, order_id) values (v_coupon.id, auth.uid(), v_order); end if; for v_item in select * from public.cart_items where cart_id = v_cart loop select * into v_product from public.products where id = v_item.product_id; insert into public.order_items (order_id, product_id, product_name, sku, unit_price, quantity, line_total) values (v_order, v_product.id, v_product.name, v_product.sku, coalesce(v_product.sale_price, v_product.original_price), v_item.quantity, coalesce(v_product.sale_price, v_product.original_price) * v_item.quantity); update public.products set stock_quantity = stock_quantity - v_item.quantity where id = v_product.id; end loop; delete from public.cart_items where cart_id = v_cart; return v_number; end; $$;
revoke all on function public.create_cod_order(jsonb, text) from public; grant execute on function public.create_cod_order(jsonb, text) to authenticated;
